// float: loop finito dentro da cena
const sceneDur = 6; // duração da cena em s
tl.fromTo(el, { y: 0 }, { y: -12, duration: 1.2, ease: "sine.inOut", yoyo: true, repeat: Math.floor(sceneDur / 1.2) - 1 }, t);

// blink loop: alterna a cada 0.5s
const sceneDur = 5;
for (let k = 0; k < sceneDur / 0.5; k++) tl.set(el, { opacity: (k + 1) % 2 }, t + k * 0.5);

// blob morph: MorphSVGPlugin; el = <path>, shapes = d dos blobs (fixos)
const sceneDur = 9, step = 1.5;
const shapes = ["M200,60 C280,60 340,140 320,220 C300,300 200,340 130,300 C60,260 60,140 200,60Z",
                "M210,50 C300,80 330,170 300,240 C270,310 170,330 110,280 C50,230 100,60 210,50Z",
                "M190,70 C260,40 350,120 330,200 C310,290 220,320 150,310 C80,300 90,110 190,70Z"];
for (let k = 0; k < Math.floor(sceneDur / step); k++) {
  tl.fromTo(el, { morphSVG: shapes[k % 3] }, { morphSVG: shapes[(k + 1) % 3], duration: step, ease: "sine.inOut", immediateRender: k === 0 }, t + k * step);
}

// breathing: loop finito
const sceneDur = 8;
tl.fromTo(el, { scale: 1, opacity: 0.9 }, { scale: 1.03, opacity: 1, duration: 2, ease: "sine.inOut", yoyo: true, repeat: Math.floor(sceneDur / 2) - 1 }, t);

// bubble rise: tabela fixa de durações/atrasos; repeat finito
const sceneDur = 9, durs = [3, 3.6, 4.2, 3.3, 4.5, 3.9];
items.forEach((b, i) => {
  const d = durs[i % durs.length], start = i * 0.4, left = sceneDur - start; // o atraso também conta
  tl.fromTo(b, { y: 0, opacity: 0.5 }, { y: -1920, opacity: 0, duration: d, ease: "none", repeat: Math.max(0, Math.floor(left / d) - 1) }, t + start);
  tl.fromTo(b, { x: -10 }, { x: 10, duration: 0.8, ease: "sine.inOut", yoyo: true, repeat: Math.max(0, Math.floor(left / 0.8) - 1) }, t + start);
});

// drift: velocidade constante pela cena toda
const sceneDur = 6, speed = 40;
tl.fromTo(el, { x: 0, y: 0 }, { x: speed * sceneDur, y: -speed * sceneDur * 0.2, duration: sceneDur, ease: "none" }, t);

// gradient shift: el = camada de gradiente com 300% do tamanho da cena
const sceneDur = 8;
tl.fromTo(el, { x: 0, y: 0, rotation: 0 }, { x: -300, y: -150, rotation: 8, duration: 4, ease: "sine.inOut", yoyo: true, repeat: Math.floor(sceneDur / 4) - 1 }, t);

// idle bob: sobe e desce curto, origem na base
const sceneDur = 4;
tl.fromTo(el, { y: 0, scaleY: 1, transformOrigin: "50% 100%" }, { y: -6, scaleY: 1.02, duration: 0.4, ease: "power1.inOut", yoyo: true, repeat: Math.floor(sceneDur / 0.4) - 1 }, t);

// flicker: rajadas fixas separadas por trechos estáveis
const f = 1 / 30, burst = [1, 0.3, 1, 1, 0.15, 0.8, 1], sceneDur = 6, gap = 1.5;
for (let b = 0; b * gap < sceneDur; b++) {
  burst.forEach((o, k) => tl.set(el, { opacity: o }, t + b * gap + k * f));
}

// light sweep: a = faixa de luz dentro de el (overflow hidden)
const sceneDur = 5, gap = 2.5;
tl.fromTo(a, { xPercent: -100, skewX: -20, opacity: 0.5 }, { xPercent: 200, duration: 0.8, ease: "power2.inOut", repeat: Math.floor(sceneDur / gap) - 1, repeatDelay: gap - 0.8 }, t);

// marquee: el = trilho com o conteúdo duplicado (2 cópias)
const sceneDur = 12, cyc = 6;
tl.fromTo(el, { xPercent: 0 }, { xPercent: -50, duration: cyc, ease: "none", repeat: Math.max(0, Math.floor(sceneDur / cyc) - 1) }, t);

// orbit: items = braços (pivô no centro); cada braço tem 1 satélite filho
const sceneDur = 6, secPerTurn = 6, turns = 360 * (sceneDur / secPerTurn);
items.forEach((arm, i) => {
  const start = (360 / items.length) * i;
  tl.fromTo(arm, { rotation: start }, { rotation: start + turns, duration: sceneDur, ease: "none" }, t);
  tl.fromTo(arm.firstElementChild, { rotation: -start }, { rotation: -start - turns, duration: sceneDur, ease: "none" }, t);
});

// pulse ring loop: items = 2 anéis no mesmo centro
const sceneDur = 6, cyc = 1.2;
items.forEach((r, i) => {
  tl.fromTo(r, { scale: 1, opacity: 0.6 }, { scale: 2.5, opacity: 0, duration: cyc, ease: "power1.out", repeat: Math.floor(sceneDur / cyc) - 2 }, t + i * cyc / 2);
});

// rotate loop: velocidade constante, finito
const sceneDur = 6, secPerTurn = 8;
tl.fromTo(el, { rotation: 0 }, { rotation: 360 * (sceneDur / secPerTurn), duration: sceneDur, ease: "none" }, t);

// shimmer: sequência fixa de brilhos (determinística)
const sceneDur = 4, seq = [1.05, 0.96, 1.12, 1.0, 1.18, 0.93, 1.08, 1.02];
const steps = Math.floor(sceneDur / 0.1);
for (let k = 0; k < steps; k++) tl.set(el, { filter: "brightness(" + seq[(k * 3) % seq.length] + ")" }, t + k * 0.1);

// sparkle loop: atrasos fixos por estrela; repeat finito
const sceneDur = 6, cycle = 1.5, delays = [0, 0.35, 0.7, 0.2, 1.05];
items.forEach((s, i) => {
  const delay = delays[i % delays.length], reps = Math.max(0, Math.floor((sceneDur - delay - 0.6) / cycle)); // o atraso também conta
  tl.fromTo(s, { scale: 0, rotation: 0, opacity: 1 }, { keyframes: { scale: [0, 1, 0], rotation: [0, 45, 90] }, duration: 0.6, ease: "none", repeat: reps, repeatDelay: cycle - 0.6 }, t + delay);
});

// jitter 12 fps: tabela fixa de poses
const sceneDur = 5, poses = [[1, -1, 0.4], [-2, 1, -0.6], [0, 2, 0.2], [2, 0, -0.3], [-1, -2, 0.5]];
for (let k = 0; k < sceneDur * 12; k++) {
  const [x, y, r] = poses[(k * 2) % poses.length];
  tl.set(el, { x, y, rotation: r }, t + k / 12);
}

// sway: preso pela base
const sceneDur = 6.4;
tl.fromTo(el, { rotation: -3, transformOrigin: "50% 100%" }, { rotation: 3, duration: 1.6, ease: "sine.inOut", yoyo: true, repeat: Math.floor(sceneDur / 1.6) - 1 }, t);

// tilt loop: pai com perspective: 1200px; períodos diferentes por eixo
const sceneDur = 8;
tl.fromTo(el, { rotationY: -12 }, { rotationY: 12, duration: 2, ease: "sine.inOut", yoyo: true, repeat: Math.floor(sceneDur / 2) - 1 }, t);
tl.fromTo(el, { rotationX: 8 }, { rotationX: -8, duration: 2.6, ease: "sine.inOut", yoyo: true, repeat: Math.floor(sceneDur / 2.6) - 1 }, t);

// wave: fila de itens com defasagem fixa; repeat dentro do stagger (por item, finito)
// no nível de cima o repeat repetiria a onda inteira e passaria da cena
const sceneDur = 4, half = 0.35, each = 0.1;
const pairs = Math.floor((sceneDur - each * (items.length - 1)) / (2 * half)); // idas e voltas que cabem
tl.fromTo(items, { y: 0 }, { y: -18, duration: half, ease: "sine.inOut", stagger: { each, repeat: Math.max(1, pairs * 2) - 1, yoyo: true } }, t);
